import sys

def solve():
    # Read input from stdin
    # The input format usually depends on the environment, 
    # but based on the prompt, we expect a list of integers.
    # Since the input is provided as a list in the example, 
    # we will handle reading a comma-separated or space-separated line.
    input_data = sys.stdin.read().strip()
    if not input_data:
        return

    # Clean the input string to handle cases like "[1,2,3]" or "1 2 3"
    input_data = input_data.replace('[', '').replace(']', '').replace(',', ' ')
    nums = list(map(int, input_data.split()))

    if not nums:
        print(0)
        return

    # Step 1: Count frequencies of each element
    freq_map = {}
    for num in nums:
        freq_map[num] = freq_map.get(num, 0) + 1

    # Step 2: Find the maximum frequency
    max_freq = 0
    for freq in freq_map.values():
        if freq > max_freq:
            max_freq = freq

    # Step 3: Sum frequencies of all elements that have the max_freq
    total_max_freq_elements = 0
    for freq in freq_map.values():
        if freq == max_freq:
            total_max_freq_elements += freq

    print(total_max_freq_elements)

if __name__ == "__main__":
    solve()

import sys
import ast

def solve():
    # Read input from stdin
    try:
        input_data = sys.stdin.read().strip()
        if not input_data:
            return
        # Convert the input string to a Python list
        dimensions = ast.literal_eval(input_data)
    except Exception:
        return

    max_diag_sq = -1
    max_area = -1

    for length, width in dimensions:
        # Calculate squared diagonal length to avoid floating point issues
        diag_sq = length**2 + width**2
        area = length * width

        # If we find a longer diagonal, update both max_diag_sq and max_area
        if diag_sq > max_diag_sq:
            max_diag_sq = diag_sq
            max_area = area
        # If the diagonals are equal, take the one with the maximum area
        elif diag_sq == max_diag_sq:
            if area > max_area:
                max_area = area

    print(max_area)

if __name__ == "__main__":
    solve()

import sys

def solve():
    # Read input from stdin
    # The input might be provided as a quoted string or just the string itself
    # based on common competitive programming formats.
    line = sys.stdin.read().strip()
    if not line:
        return

    # Handle cases where input might be passed as s = "string"
    if line.startswith('s = "') and line.endswith('"'):
        s = line[5:-1]
    elif line.startswith('"') and line.endswith('"'):
        s = line[1:-1]
    else:
        s = line

    # The logic to count key changes
    changes = 0
    for i in range(1, len(s)):
        # Compare characters in lowercase to ignore case differences
        if s[i].lower() != s[i-1].lower():
            changes += 1

    print(changes)

if __name__ == "__main__":
    solve()

import sys

def solve():
    # Read input from stdin
    try:
        line = sys.stdin.read().strip()
        if not line:
            return

        # Assuming input format is like [3,2,1,4,5] or just numbers separated by spaces
        # We handle both common formats for competitive programming
        if line.startswith('['):
            # Handle list format [3,2,1,4,5]
            line = line.strip('[]')
            if not line:
                print(0)
                return
            nums = [int(x.strip()) for x in line.split(',')]
        else:
            # Handle space separated numbers
            nums = [int(x) for x in line.split()]

        if len(nums) < 2:
            print(0)
            return

        # The first operation defines the required score
        target_score = nums[0] + nums[1]
        operations_count = 1

        # Iterate through the array in pairs starting from index 2
        for i in range(2, len(nums) - 1, 2):
            current_score = nums[i] + nums[i+1]
            if current_score == target_score:
                operations_count += 1
            else:
                # Stop as soon as the score differs
                break

        print(operations_count)

    except EOFError:
        pass

if __name__ == "__main__":
    solve()

import sys

def solve():
    # Read N from standard input
    try:
        line = sys.stdin.readline()
        if not line:
            return
        n = int(line.strip())
    except ValueError:
        return

    # Lexicographical order means we iterate x, then y, then z
    # x ranges from 0 to N
    for x in range(n + 1):
        # For a fixed x, y can range from 0 up to N - x
        for y in range(n - x + 1):
            # For fixed x and y, z can range from 0 up to N - x - y
            for z in range(n - x - y + 1):
                print(f"{x} {y} {z}")

if __name__ == "__main__":
    solve()

import sys

def main():
    # Read input from stdin
    try:
        line = sys.stdin.read().strip()
        if not line:
            return
        n = int(line)
    except EOFError:
        return

    # If n is 0, ctz is technically undefined for positive integers, 
    # but the constraints say 1 <= N.
    if n == 0:
        print(0)
        return

    count = 0
    # While n is even, divide by 2 and increment the count
    while n > 0 and n % 2 == 0:
        count += 1
        n //= 2

    print(count)

