import sys

def solve():
    # Read the input string S
    try:
        line = sys.stdin.readline()
        if not line:
            return
        s = line.strip()
    except EOFError:
        return

    # An Extended ABC string is a string that matches the regular expression ^A*B*C*$
    # This means all A's must come before all B's, and all B's must come before all C's.

    # We can check this by verifying if the string is sorted.
    # Since 'A' < 'B' < 'C' in lexicographical order, any string consisting 
    # only of A, B, and C that follows the order A*B*C* will be sorted.

    if list(s) == sorted(s):
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()

