import sys

def solve():
    # Read input from standard input
    try:
        line = sys.stdin.readline()
        if not line:
            return
        # Split the input string to get A and B
        parts = line.split()
        if len(parts) < 2:
            return
        a = int(parts[0])
        b = int(parts[1])
    except EOFError:
        return

    # The set of all suspects
    suspects = {1, 2, 3}

    # Ringo says person A is not the culprit
    # Snuke says person B is not the culprit
    # The culprit must be someone who is NOT A and NOT B
    possible_culprits = suspects - {a, b}

    # If there is exactly one person left in the set of possible culprits,
    # then the culprit is uniquely identified.
    if len(possible_culprits) == 1:
        # Print the only element in the set
        print(list(possible_culprits)[0])
    else:
        # Otherwise, the culprit cannot be uniquely identified
        print("-1")

if __name__ == "__main__":
