import sys

def solve():
    # Read input from stdin
    try:
        line = sys.stdin.read().strip()
        if not line:
            return
        # If the input is provided as "s = 'string'", extract the string
        if line.startswith("s ="):
            s = line.split('=', 1)[1].strip().strip('"').strip("'")
        else:
            s = line.strip('"').strip("'")
    except EOFError:
        return

    left = 0
    max_len = 0
    counts = {}

    for right in range(len(s)):
        char_right = s[right]
        counts[char_right] = counts.get(char_right, 0) + 1

        # If the character count exceeds 2, shrink window from the left
        while counts[char_right] > 2:
            char_left = s[left]
            counts[char_left] -= 1
            left += 1

        # Update the maximum length found
        max_len = max(max_len, right - left + 1)

    print(max_len)

if __name__ == "__main__":
    solve()

