import sys

def solve():
    # Read input from stdin
    line = sys.stdin.read().strip()
    if not line:
        return

    # The input might be wrapped in quotes or provided as a simple string
    s = line.strip('"')

    res = list(s)

    # Handle Hour first digit s[0]
    if res[0] == '?':
        # If s[1] is '?', we can use '1' for s[0] and '1' for s[1] (11:MM)
        # If s[1] is '0' or '1', we can use '1' for s[0] (10:MM or 11:MM)
        # If s[1] is '2'-'9', s[0] must be '0' (02:MM to 09:MM)
        if res[1] == '?' or res[1] == '0' or res[1] == '1':
            res[0] = '1'
        else:
            res[0] = '0'

    # Handle Hour second digit s[1]
    if res[1] == '?':
        # If s[0] is '1', max s[1] is '1'
        # If s[0] is '0', max s[1] is '9'
        if res[0] == '1':
            res[1] = '1'
        else:
            res[1] = '9'

    # Handle Minute first digit s[3]
    if res[3] == '?':
        res[3] = '5'

    # Handle Minute second digit s[4]
    if res[4] == '?':
