import sys

def solve():
    # Read input from stdin
    # The input format is expected to be the string word
    # Since the starter code provides a function signature, 
    # we adapt it to read from standard input.
    input_data = sys.stdin.read().strip()

    # If the input is wrapped in quotes (like "aaAbcBC"), remove them
    if len(input_data) >= 2 and input_data[0] == '"' and input_data[-1] == '"':
        word = input_data[1:-1]
    else:
        word = input_data

    # Sets to store lowercase and uppercase characters found in the word
    lower_set = set()
    upper_set = set()

    for char in word:
        if char.islower():
            lower_set.add(char)
        elif char.isupper():
            upper_set.add(char)

    # Count how many lowercase letters have a corresponding uppercase letter
    special_count = 0
    for char in lower_set:
        if char.upper() in upper_set:
            special_count += 1

    print(special_count)

if __name__ == "__main__":
