def solve():
    # Read input from stdin
    try:
        line = sys.stdin.read().strip()
        if not line:
            return
        n = int(line)
    except EOFError:
        return
    except ValueError:
        return

    # Alice starts by removing 10 stones
    stones_to_remove = 10
    current_player = "Alice"

    while n >= 0:
        if n < stones_to_remove:
            # Current player cannot make a move, so they lose.
            # If Alice cannot move, Bob wins (False).
            # If Bob cannot move, Alice wins (True).
            if current_player == "Alice":
                print("false")
            else:
                print("true")
            return

        # Perform the move
        n -= stones_to_remove

        # Prepare for the next turn
        stones_to_remove -= 1
        # Switch player
        current_player = "Bob" if current_player == "Alice" else "Alice"

