def solve():
    # Read input from stdin
    # Since the input format is not explicitly provided as a raw string, 
    # we assume the input is given as a comma-separated list or similar.
    # For standard competitive programming, we read the line and parse it.
    try:
        input_data = sys.stdin.read().strip()
        if not input_data:
