        count = 0
        # Iterate through the array to find subarrays of length 3
        for i in range(len(nums) - 2):
            # Condition: first + third == second / 2
            # Rewritten as: 2 * (first + third) == second
            if 2 * (nums[i] + nums[i+2]) == nums[i+1]:
                count += 1

        print(count)
    except EOFError:
        pass
    except Exception:
        pass

