import sys

def solve():
    # Read N from standard input
    try:
        line = sys.stdin.readline()
        if not line:
            return
        n = int(line.strip())
    except ValueError:
        return

    # Initialize the grid. 
    # We use a 2D list to store the colors.
    # '?' represents uncolored, '#' for black, '.' for white.
    grid = [['?' for _ in range(n)] for _ in range(n)]

    # Perform the operations for i = 1 to N
    for i_val in range(1, n + 1):
        j_val = n + 1 - i_val

        # Condition: i <= j
        if i_val <= j_val:
            # Determine the color based on whether i is odd or even
            color = '#' if i_val % 2 != 0 else '.'

            # The rectangular region is from (i, i) to (j, j)
            # Convert 1-based indexing to 0-based indexing
            # Top-left: (i_val-1, i_val-1), Bottom-right: (j_val-1, j_val-1)
            for r in range(i_val - 1, j_val):
                for c in range(i_val - 1, j_val):
                    grid[r][c] = color
        else:
            # If i > j, do nothing
            pass

    # Print the final grid
    for row in grid:
        print("".join(row))

if __name__ == "__main__":
    solve()

