import sys

def solve():
    # Read N from the first line
    try:
        line1 = sys.stdin.readline()
        if not line1:
            return
        n = int(line1.strip())

        # Read P_i from the subsequent lines
        p = []
        while len(p) < n:
            line = sys.stdin.readline()
            if not line:
                break
            p.extend(map(int, line.split()))
    except ValueError:
        return

    # To determine the rank, we need to know how many people have a score 
    # strictly greater than the score of person i.
    # The rank of person i is (number of people with score > P_i) + 1.

    ranks = []
    for i in range(n):
        current_score = p[i]
        # Count how many people have a score strictly greater than current_score
        count_greater = 0
        for score in p:
            if score > current_score:
                count_greater += 1

        # Rank is 1 + the number of people who performed better
        ranks.append(count_greater + 1)

    # Print each rank on a new line
    for r in ranks:
        print(r)

if __name__ == "__main__":
    solve()

