def solve():
    # Read input from stdin
    input_data = sys.stdin.read().strip()
    if not input_data:
        return

    # The input is expected to be a JSON-like list of lists
    try:
        grid = json.loads(input_data)
    except json.JSONDecodeError:
        # Handle cases where input might not be perfect JSON
        return

    n = len(grid)
    m = len(grid[0])

    result = []
    keep = True  # Flag to determine if we keep the current cell

    for r in range(n):
        # Determine column traversal order
        if r % 2 == 0:
            # Left to right
            cols = range(m)
        else:
            # Right to left
            cols = range(m - 1, -1, -1)

        for c in cols:
            if keep:
                result.append(grid[r][c])
            # Toggle keep for every cell encountered in the zigzag path
            keep = not keep

    print(result)

