import sys

def solve():
    # Reading input from stdin
    # The input format is expected to be a list representation like [1,2,4]
    # or space separated integers. Let's handle common formats.
    try:
        line = sys.stdin.read().strip()
        if not line:
            return

        # Handle [1,2,3] format
        if line.startswith('[') and line.endswith(']'):
            line = line[1:-1]

        # Split by comma or space and convert to integers
        if ',' in line:
            nums = [int(x.strip()) for x in line.split(',') if x.strip()]
        else:
            nums = [int(x.strip()) for x in line.split() if x.strip()]

        if not nums:
            return

        n = len(nums)
        max_diff = 0

        # Check adjacent elements in the linear part of the array
        for i in range(n - 1):
            diff = abs(nums[i] - nums[i+1])
            if diff > max_diff:
                max_diff = diff

        # Check the circular connection (last and first element)
        circular_diff = abs(nums[n-1] - nums[0])
        if circular_diff > max_diff:
            max_diff = circular_diff

        print(max_diff)

    except EOFError:
        pass
    except Exception:
        pass

if __name__ == "__main__":
    solve()

import sys

def solve():
    # Read input from stdin
    input_data = sys.stdin.read().strip()
    if not input_data:
        return

    # The input might be passed as a string directly or inside quotes
    # Cleaning input in case it's provided as "s = '...'"
    s = input_data
    if s.startswith('s = "') and s.endswith('"'):
        s = s[5:-1]
    elif s.startswith('s = \'') and s.endswith('\''):
        s = s[5:-1]
    elif s.startswith('"') and s.endswith('"'):
        s = s[1:-1]
    elif s.startswith("'") and s.endswith("'"):
        s = s[1:-1]

    # Pre-calculate frequencies of each digit in the string
    counts = {}
    for char in s:
        counts[char] = counts.get(char, 0) + 1

    # Iterate through the string to find the first valid pair
    for i in range(len(s) - 1):
        d1 = s[i]
        d2 = s[i+1]

        # Condition 1: The first digit is not equal to the second
        if d1 != d2:
            # Condition 2: Each digit appears as many times as its numeric value
            val1 = int(d1)
            val2 = int(d2)
            if counts.get(d1, 0) == val1 and counts.get(d2, 0) == val2:
                print(d1 + d2)
                return

    # If no valid pair is found, return an empty string
    print("")

if __name__ == "__main__":
    solve()

