    # Removing brackets and splitting by comma
    try:
        cleaned_input = input_data.replace('[', '').replace(']', '').replace(' ', '')
        if not cleaned_input:
            nums = []
        else:
            nums = [int(x) for x in cleaned_input.split(',')]
    except ValueError:
        return

    # Step 1: Replace even numbers with 0 and odd numbers with 1
    transformed = []
    for num in nums:
        if num % 2 == 0:
            transformed.append(0)
        else:
            transformed.append(1)

    # Step 2: Sort the modified array in non-decreasing order
    transformed.sort()

    # Print the resulting array in the required format
